#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/types.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// ScrollableControl's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/scrollable_control.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// Whether scroll bars appear when the content exceeds the client area (AutoScroll).
template <typename Declaring>
struct AutoScrollCapability {
    PropertyCell<bool, AutoScrollCapability<Declaring>> auto_scroll{false};

    static void assign(AutoScrollCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.auto_scroll), incoming);
        if (!capability.auto_scroll.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.auto_scroll));
    }
};

// Logical space kept around the content when scrolling; nonnegative (AutoScrollMargin).
template <typename Declaring>
struct AutoScrollMarginCapability {
    PropertyCell<Size, AutoScrollMarginCapability<Declaring>> auto_scroll_margin{};

    static void assign(AutoScrollMarginCapability& capability, Size incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.auto_scroll_margin), incoming);
        if (!capability.auto_scroll_margin.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.auto_scroll_margin));
    }
};

// Smallest logical content size scrolling allows for; nonnegative (AutoScrollMinSize).
template <typename Declaring>
struct AutoScrollMinSizeCapability {
    PropertyCell<Size, AutoScrollMinSizeCapability<Declaring>> auto_scroll_min_size{};

    static void assign(AutoScrollMinSizeCapability& capability, Size incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.auto_scroll_min_size), incoming);
        if (!capability.auto_scroll_min_size.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.auto_scroll_min_size));
    }
};

// The scrolled content's offset, negated as Windows Forms reports it (AutoScrollPosition); a write scrolls to the given position, clamped at zero.
template <typename Declaring>
struct AutoScrollPositionCapability {
    PropertyView<Point, AutoScrollPositionCapability<Declaring>> auto_scroll_position;

    static void assign(AutoScrollPositionCapability& capability, Point incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.auto_scroll_position), std::move(incoming));
    }

    static Point read(const AutoScrollPositionCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        Point current = control.read_view(capability.auto_scroll_position);
        return current;
    }
};

// Every ScrollableControl capability, in the order the declaring class takes them.
template <typename Declaring>
struct ScrollableControlCapabilities : public AutoScrollCapability<Declaring>,
                                       public AutoScrollMarginCapability<Declaring>,
                                       public AutoScrollMinSizeCapability<Declaring>,
                                       public AutoScrollPositionCapability<Declaring> {};

} // namespace gui_forms
